"""Fix round (lint) for batch TO3: rewrites data/z52b/pass2/outcome_TO3.jsonl so that every record reports the
executed main step (computations in scripts/z52d_p2_TO3_*, results in data/z52b/pass2/TO3/*.json)."""
import json
D = 'data/z52b/pass2/TO3/'
O = {}
def A(mid, outcome, summary, evidence, not_done, nxt):
    O[mid] = dict(mid=mid, outcome=outcome, summary=summary, evidence=evidence, not_done=not_done, next=nxt, prev_outcome='none')
