# ---------------- write -----------------
import sys
batch = [json.loads(l)['mid'] for l in open('data/z52b/pass2/batch_TO3.jsonl') if l.strip()]
missing = [m for m in batch if m not in O]
extra = [m for m in O if m not in batch]
print('batch', len(batch), 'records', len(O), 'missing', missing, 'extra', extra)
assert not missing and not extra
with open('data/z52b/pass2/outcome_TO3.jsonl', 'w') as f:
    for m in batch:
        f.write(json.dumps(O[m], ensure_ascii=False) + '\n')
from collections import Counter
print(Counter(o['outcome'] for o in O.values()))
